import { useState, useEffect } from "react";
import { useDispatch, useSelector } from "react-redux";
import { registerUser } from "../Features/UserSlice";
import { useNavigate, Link } from "react-router-dom";
import "../Styles/UserRegister.css";
import registerImg from "../Images/login-side.png";

import { useForm } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import { userRegisterSchema } from "../Validations/UserValidation";

const MAJORS = [
  "",
  "Information Technology",
  "Business Administration",
  "Engineering",
  "Mass Communication",
];

const UserRegister = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { isLoading, isError, isSuccess } = useSelector((state) => state.users);

  const [name, setname] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [major, setMajor] = useState("");
  const [age, setAge] = useState("");

  const {
    register,
    handleSubmit,
    formState: { errors },
    trigger,
  } = useForm({
    resolver: yupResolver(userRegisterSchema),
  });

  const onSubmit = (data) => {
    try {
      dispatch(registerUser(data));
    } catch (error) {
      console.log(error);
    }
  };

  useEffect(() => {
    if (isSuccess) {
      alert("Student Registered");
      navigate("/userprofile");
    } else if (isError) {
      alert("Registration failed. Try again.");
    }
  }, [isSuccess, isError, navigate]);
  useEffect(() => {
    if (isSuccess) {
      alert("Student Registered");
      navigate("/userprofile");
    } else if (isError) {
      alert("Registration failed. Try again.");
    }
  }, [isSuccess, isError, navigate]);

  return (
    <div className="register-page">
      <div className="register-container">
        <div className="register-form">
          <h1 className="reg-title">
            Create your <span className="accent">account</span>
          </h1>
          <p className="reg-sub">Please fill in your details to continue</p>

          <div className="role-switch">
            <Link to="/user-register" className="role-btn active">
              Student
            </Link>
            <Link to="/company-register" className="role-btn">
              Company
            </Link>
          </div>

          <form onSubmit={handleSubmit(onSubmit)}>
            <label>Full Name</label>
            <input
              type="text"
              placeholder="Your name"
              {...register("name")}
              value={name}
              onChange={(e) => {
                setname(e.target.value);
                trigger("name");
              }}
            />
            <p className="error">{errors.name?.message}</p>

            <label>Email</label>
            <input
              type="email"
              placeholder="you@example.com"
              {...register("email")}
              value={email}
              onChange={(e) => {
                setEmail(e.target.value);
                trigger("email");
              }}
            />
            <p className="error">{errors.email?.message}</p>

            <label>Password</label>
            <input
              type="password"
              placeholder="********"
              {...register("password")}
              value={password}
              onChange={(e) => {
                setPassword(e.target.value);
                trigger("password");
              }}
            />
            <p className="error">{errors.password?.message}</p>

            <div className="row-flex">
              <div className="col-half">
                <label>Major</label>
                <select
                  {...register("major")}
                  value={major}
                  onChange={(e) => {
                    setMajor(e.target.value);
                    trigger("major");
                  }}
                >
                  {MAJORS.map((m, i) => (
                    <option key={i} value={m}>
                      {m === "" ? "Select your major" : m}
                    </option>
                  ))}
                </select>
                <p className="error">{errors.major?.message}</p>
              </div>

              <div className="col-half">
                <label>Age</label>
                <input
                  type="number"
                  min="17"
                  max="45"
                  {...register("age")}
                  value={age}
                  onChange={(e) => {
                    setAge(e.target.value);
                    trigger("age");
                  }}
                />
                <p className="error">{errors.age?.message}</p>
              </div>
            </div>

            <button type="submit" className="reg-btn" disabled={isLoading}>
              {isLoading ? "Registering..." : "Sign up"}
            </button>

            <p className="login-text">
              Already have an account?{" "}
              <Link to="/login" className="login-link">
                Log in now!
              </Link>
            </p>
          </form>
        </div>

        <div className="register-image">
          <img src={registerImg} alt="Registration illustration" />
        </div>
      </div>
    </div>
  );
};

export default UserRegister;
